//! AWS Lambda demo built on Salvo's serverless runtime.
//!
//! This example shows the full surface of the Lambda adapter:
//!
//! - plain-text and JSON responses
//! - path and query parameter extraction
//! - JSON request body parsing
//! - Lambda event data access (`LambdaRequestExt`)
//! - streaming responses (`LambdaServer::handle_streaming` + `run_with_streaming_response`)
//!
//! Build and deploy it with:
//!
//! ```text
//! cargo lambda build --release
//! cargo lambda deploy
//! ```
//!
//! The entry point is generated by `#[service(start = init)]`, which drives the
//! same `build()` router through the streaming Lambda runtime
//! (`run_with_streaming_response`), so unbounded responses are forwarded
//! chunk by chunk.

use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

use salvo::prelude::*;
use salvo::serverless::lambda::LambdaRequestExt;
use salvo::serverless::tokio;
use serde::{Deserialize, Serialize};

/// JSON payload echoed back by `POST /echo`.
#[derive(Debug, Deserialize, Serialize)]
struct EchoPayload {
    /// Message to echo.
    message: String,
}

/// In-memory object store backing the upload/download demo endpoints.
///
/// Lambda is stateless across cold starts: this map only lives for the lifetime
/// of a single warm container, which is enough to demonstrate the upload and
/// download flow from the embedded browser test page.
static OBJECTS: OnceLock<Mutex<HashMap<String, Vec<u8>>>> = OnceLock::new();

/// Returns the shared object store.
fn objects() -> &'static Mutex<HashMap<String, Vec<u8>>> {
    OBJECTS.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Returns the sorted list of keys currently stored.
fn object_keys() -> Vec<String> {
    let mut keys: Vec<String> = objects().lock().unwrap().keys().cloned().collect();
    keys.sort();
    keys
}

/// One-time warm-start initialization.
///
/// `TracingLog` builds the subscriber at runtime, so nothing is read from a
/// configuration file. This runs once before the Lambda runtime begins polling
/// for events.
fn init() {
    let config = LogConfig::new().level("info").filter("salvo=debug");
    if let Err(err) = TracingLog::init(&config) {
        eprintln!("failed to initialize tracing: {err}");
    }
}

/// `GET /hello` — plain-text greeting.
#[handler]
async fn hello() -> &'static str {
    "Hello from AWS Lambda"
}

/// `GET /hello/{name}` — reads a path parameter.
#[handler]
async fn hello_name(req: &mut Request, res: &mut Response) {
    let name = req
        .param::<String>("name")
        .unwrap_or_else(|| "world".into());
    res.render(Text::Plain(format!("Hello, {name}!")));
}

/// `GET /greet?name=...` — reads a query parameter.
#[handler]
async fn greet(req: &mut Request, res: &mut Response) {
    let name = req
        .query::<String>("name")
        .unwrap_or_else(|| "stranger".into());
    res.render(Text::Plain(format!("Hi, {name}!")));
}

/// `POST /echo` — parses a JSON body and echoes it back as JSON.
#[handler]
async fn echo_json(req: &mut Request, res: &mut Response) {
    match req.parse_json::<EchoPayload>().await {
        Ok(payload) => res.render(Json(payload)),
        Err(err) => {
            res.status_code(StatusCode::BAD_REQUEST);
            res.render(Text::Plain(err.to_string()));
        }
    }
}

/// `GET /event` — reads Lambda event data exposed by [`LambdaRequestExt`].
#[handler]
async fn event_info(req: &mut Request, res: &mut Response) {
    let request_id = req
        .lambda_context()
        .map_or("unknown", |ctx| ctx.request_id.as_str());
    res.render(Json(serde_json::json!({
        "lambda_request_id": request_id,
        "request_context_present": req.request_context().is_some(),
        "raw_http_path": req.raw_http_path(),
        "query_string_parameters_present": req.query_string_parameters().is_some_and(|q| !q.is_empty()),
        "path_parameters_present": req.path_parameters().is_some_and(|p| !p.is_empty()),
        "stage_variables_present": req.stage_variables().is_some_and(|s| !s.is_empty()),
    })));
}

/// `GET /stream` — 流式返回若干纯文本分块。streams several plain-text chunks.
///
/// `res.channel()` 返回一个基于零容量（会合式）通道的 body sender：每次
/// `send_data` 都会阻塞，直到运行时开始 poll 响应体。因此发送循环必须放到
/// `tokio::spawn` 的任务里；若在当前 handler 内同步发送，会因为响应体要等
/// handler 返回后才被 poll 而形成死锁。sender 被 drop 后即结束流。
/// `res.channel()` returns a body sender backed by a zero-capacity (rendezvous)
/// channel: each `send_data` blocks until the runtime polls the response body.
/// The send loop must therefore run in a spawned task; sending synchronously
/// would deadlock because the body is only polled after the handler returns.
/// Dropping the sender ends the stream.
#[handler]
async fn stream(res: &mut Response) {
    res.add_header("content-type", "text/plain", true).ok();
    let mut sender = res.channel();
    tokio::spawn(async move {
        for i in 0..5 {
            if sender.send_data(format!("chunk {i}\n")).await.is_err() {
                return;
            }
        }
    });
}

/// `GET /objects` — lists the keys stored by the upload demo.
#[handler]
async fn list_objects(res: &mut Response) {
    res.render(Json(serde_json::json!({ "objects": object_keys() })));
}

/// `PUT /objects/{key}` — stores the raw request body under `key`.
#[handler]
async fn put_object(req: &mut Request, res: &mut Response) {
    let Some(key) = req.param::<String>("key") else {
        res.status_code(StatusCode::BAD_REQUEST);
        res.render(Text::Plain("missing {key} path parameter"));
        return;
    };
    let Ok(bytes) = req.payload().await else {
        res.status_code(StatusCode::BAD_REQUEST);
        res.render(Text::Plain("failed to read request body"));
        return;
    };
    let len = bytes.len();
    objects()
        .lock()
        .unwrap()
        .insert(key.clone(), bytes.to_vec());
    res.render(Json(serde_json::json!({ "key": key, "size": len })));
}

/// `GET /objects/{key}` — downloads the stored bytes.
#[handler]
async fn get_object(req: &mut Request, res: &mut Response) {
    let Some(key) = req.param::<String>("key") else {
        res.status_code(StatusCode::BAD_REQUEST);
        res.render(Text::Plain("missing {key} path parameter"));
        return;
    };
    let bytes = objects().lock().unwrap().get(&key).cloned();
    match bytes {
        Some(bytes) => {
            res.add_header("content-type", "application/octet-stream", true)
                .ok();
            res.add_header(
                "content-disposition",
                format!("attachment; filename=\"{key}\""),
                true,
            )
            .ok();
            if res.write_body(bytes).is_err() {
                res.status_code(StatusCode::INTERNAL_SERVER_ERROR);
            }
        }
        None => {
            res.status_code(StatusCode::NOT_FOUND);
            res.render(Text::Plain(format!("object `{key}` not found")));
        }
    }
}

/// `DELETE /objects/{key}` — deletes a stored object.
#[handler]
async fn delete_object(req: &mut Request, res: &mut Response) {
    let Some(key) = req.param::<String>("key") else {
        res.status_code(StatusCode::BAD_REQUEST);
        res.render(Text::Plain("missing {key} path parameter"));
        return;
    };
    match objects().lock().unwrap().remove(&key) {
        Some(_) => res.render(Text::Plain(format!("deleted `{key}`"))),
        None => {
            res.status_code(StatusCode::NOT_FOUND);
            res.render(Text::Plain(format!("object `{key}` not found")));
        }
    }
}

/// `GET /` — serves the embedded browser test page that exercises every endpoint.
#[handler]
async fn index_page(res: &mut Response) {
    res.render(Text::Html(include_str!("../static/index.html")));
}

/// Builds the Lambda router.
///
/// `#[service(start = init)]` generates the streaming Lambda entry point that
/// drives this router via `run_with_streaming_response` + `handle_streaming`.
#[service(start = init)]
fn build() -> Router {
    Router::new()
        .push(Router::with_path("hello").get(hello))
        .push(Router::with_path("hello/{name}").get(hello_name))
        .push(Router::with_path("greet").get(greet))
        .push(Router::with_path("echo").post(echo_json))
        .push(Router::with_path("event").get(event_info))
        .push(Router::with_path("stream").get(stream))
        .push(
            Router::with_path("objects").get(list_objects).push(
                Router::with_path("{key}")
                    .get(get_object)
                    .put(put_object)
                    .delete(delete_object),
            ),
        )
        .push(Router::with_path("/").get(index_page))
        .push(Router::with_path("index.html").get(index_page))
}